<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import type { BancoProveedor,CuentaBancariaPayload,CuentaBancariaProveedor,MonedaProveedor,ProveedorFinanzas } from '../interfaces/cuenta-bancaria-proveedor.interface'
import { buscarProveedoresFinanzas,cambiarEstadoCuentaProveedor,establecerCuentaDetracciones,establecerCuentaPrincipal,guardarCuentaProveedor,listarCuentasProveedor,obtenerCuentaProveedor,obtenerOpcionesCuentasProveedor } from '../services/cuenta-bancaria-proveedor'
const blank=(proveedorId=0):CuentaBancariaPayload=>({proveedor_id:proveedorId,banco_id:0,moneda_id:0,tipo_cuenta:'CORRIENTE',numero_cuenta:'',cci:'',principal:false,es_cuenta_detracciones:false})
const query=ref(''),results=ref<ProveedorFinanzas[]>([]),selected=ref<ProveedorFinanzas|null>(null),rows=ref<CuentaBancariaProveedor[]>([]),bancos=ref<BancoProveedor[]>([]),monedas=ref<MonedaProveedor[]>([]),loading=ref(false),error=ref(''),success=ref(''),showForm=ref(false),editing=ref<number|null>(null),form=reactive(blank())
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
async function search(){if(query.value.trim().length<4){error.value='Ingrese al menos 4 caracteres para buscar.';return}loading.value=true;error.value='';try{results.value=await buscarProveedoresFinanzas(query.value.trim())}catch(e){error.value=message(e)}finally{loading.value=false}}
async function selectProvider(item:ProveedorFinanzas){selected.value=item;query.value=item.text||item.texto||`${item.ruc} - ${item.razon_social}`;results.value=[];await reload()}
async function reload(){if(!selected.value)return;loading.value=true;try{const r=await listarCuentasProveedor(selected.value.id);selected.value=r.proveedor;rows.value=r.data}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){if(!selected.value)return;editing.value=null;Object.assign(form,blank(selected.value.id));showForm.value=true}
async function edit(item:CuentaBancariaProveedor){loading.value=true;try{const x=await obtenerCuentaProveedor(item.id);editing.value=x.id;Object.assign(form,blank(x.proveedor_id),x,{principal:Boolean(x.principal),es_cuenta_detracciones:Boolean(x.es_cuenta_detracciones)});showForm.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){loading.value=true;error.value='';try{if(form.tipo_cuenta==='DETRACCIONES')form.es_cuenta_detracciones=true;await guardarCuentaProveedor(editing.value,{...form});success.value=`Cuenta bancaria ${editing.value?'actualizada':'registrada'} correctamente.`;showForm.value=false;await reload()}catch(e){error.value=message(e)}finally{loading.value=false}}
async function action(item:CuentaBancariaProveedor,type:'estado'|'principal'|'detracciones'){const label=type==='estado'?(item.activo?'inactivar':'activar'):type==='principal'?'establecer como principal':'establecer para detracciones';if(!confirm(`¿Desea ${label} esta cuenta?`))return;loading.value=true;try{if(type==='estado')await cambiarEstadoCuentaProveedor(item.id);else if(type==='principal')await establecerCuentaPrincipal(item.id);else await establecerCuentaDetracciones(item.id);success.value='Cuenta bancaria actualizada correctamente.';await reload()}catch(e){error.value=message(e)}finally{loading.value=false}}
onMounted(async()=>{try{const x=await obtenerOpcionesCuentasProveedor();bancos.value=x.bancos;monedas.value=x.monedas}catch(e){error.value=message(e)}})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Cuentas bancarias de proveedores</nav><header class="hero"><div class="mark">CB</div><div><small>MIA · FINANZAS · PROVEEDORES</small><h1>Cuentas bancarias de proveedores</h1><p>Gestión de cuentas, CCI y cuentas de detracciones.</p></div><button v-if="selected" @click="create">+ Nueva cuenta</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="search"><label>Buscar proveedor por RUC o razón social</label><div><input v-model.trim="query" placeholder="Ingrese al menos 4 caracteres" @keyup.enter="search"><button @click="search">Buscar</button></div><ul v-if="results.length"><li v-for="item in results" :key="item.id" @click="selectProvider(item)"><b>{{item.ruc}}</b><span>{{item.razon_social}}</span></li></ul></section><section v-if="selected" class="provider"><div><small>RUC</small><b>{{selected.ruc}}</b></div><div><small>RAZÓN SOCIAL</small><b>{{selected.razon_social}}</b></div><div><small>CONTACTO</small><b>{{selected.email||'-'}} · {{selected.telefono||'-'}}</b></div></section><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!selected" class="empty">Busque y seleccione un proveedor para consultar sus cuentas.</div><div v-else-if="!rows.length" class="empty">El proveedor no tiene cuentas bancarias registradas.</div><div v-else class="scroll"><table><thead><tr><th>Banco</th><th>Moneda</th><th>Tipo</th><th>Número de cuenta</th><th>CCI</th><th>Clasificación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.banco}}</b><small>{{item.banco_codigo}}</small></td><td>{{item.moneda}}</td><td>{{item.tipo_cuenta_texto||item.tipo_cuenta}}</td><td><b>{{item.numero_cuenta}}</b></td><td>{{item.cci||'-'}}</td><td><span v-if="item.principal" class="principal">PRINCIPAL</span><span v-if="item.es_cuenta_detracciones" class="detraccion">DETRACCIONES</span></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'INACTIVA'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button v-if="item.activo&&!item.principal" @click="action(item,'principal')">Principal</button><button v-if="item.activo&&!item.es_cuenta_detracciones" class="detbtn" @click="action(item,'detracciones')">Detracción</button><button :class="item.activo?'danger':'activate'" @click="action(item,'estado')">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVA CUENTA'}}</small><h2>{{editing?'Editar':'Registrar'}} cuenta bancaria</h2><p>{{selected?.ruc}} · {{selected?.razon_social}}</p></div><button type="button" @click="showForm=false">×</button></header><div class="grid"><label>Banco<select v-model.number="form.banco_id" required><option :value="0">Seleccione</option><option v-for="x in bancos" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Moneda<select v-model.number="form.moneda_id" required><option :value="0">Seleccione</option><option v-for="x in monedas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de cuenta<select v-model="form.tipo_cuenta"><option>AHORROS</option><option>CORRIENTE</option><option>DETRACCIONES</option><option>OTRA</option></select></label><label>Número de cuenta<input v-model.trim="form.numero_cuenta" maxlength="50" required></label><label class="span2">Código de Cuenta Interbancaria (CCI)<input v-model.trim="form.cci" maxlength="30"></label></div><div class="checks"><label><input v-model="form.principal" type="checkbox"> Cuenta principal</label><label><input v-model="form.es_cuenta_detracciones" type="checkbox"> Cuenta de detracciones</label></div><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.provider small,.dialog small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.search{position:relative;margin-top:11px;padding:13px;background:#fff}.search>label{display:block;margin-bottom:5px;font-size:.5rem;font-weight:700}.search>div{display:flex;gap:6px}.search input,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.52rem}.search ul{position:absolute;z-index:5;left:13px;right:80px;margin:2px 0;padding:0;border:1px solid #d5dfe2;background:#fff;box-shadow:0 8px 20px #263d4b22;list-style:none}.search li{display:flex;gap:12px;padding:9px;border-bottom:1px solid #edf1f2;font-size:.52rem;cursor:pointer}.search li:hover{background:#edf6f7}.provider{margin-top:10px;display:grid;grid-template-columns:1fr 2fr 2fr;gap:8px}.provider div{display:grid;gap:4px;padding:12px;background:#fff}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1200px;border-collapse:collapse;font-size:.49rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.good,.bad,.principal,.detraccion{display:inline-block;margin:1px;padding:4px 7px;border-radius:10px;font-size:.45rem;font-weight:800}.good,.principal{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.detraccion{color:#77540f;background:#fff0c9}.actions{display:flex;gap:4px}.edit{background:#c98a24}.detbtn{background:#8b6824}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:55px;text-align:center;color:#849198}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(670px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0}.dialog header p{margin:0 0 15px;font-size:.5rem}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.grid label{display:grid;gap:5px;color:#5d7078;font-size:.52rem;font-weight:700}.span2{grid-column:span 2}.checks{display:flex;gap:20px;margin-top:14px;font-size:.52rem}.dialog>footer{padding:12px;display:flex;justify-content:center;gap:8px}@media(max-width:700px){.provider,.grid{grid-template-columns:1fr}.span2{grid-column:auto}.hero{flex-wrap:wrap}.hero .mark{display:none}.checks{display:grid}}
</style>
